effect.shader:
void main(){
    vec2 uv = acScreenNorm;
    if(mode==0){ if(uv.x>axis) uv.x = 2.0*axis-uv.x; }
    else if(mode==1){ if(uv.x<axis) uv.x = 2.0*axis-uv.x; }
    else if(mode==2){ if(uv.y>axis) uv.y = 2.0*axis-uv.y; }
    else if(mode==3){ if(uv.y<axis) uv.y = 2.0*axis-uv.y; }
    else { if(uv.x>0.5) uv.x=1.0-uv.x; if(uv.y>0.5) uv.y=1.0-uv.y; }
    gl_FragColor = texture2DCv(inputImg.texture, uv);
}
